/* b2b_popup_vars */

document.addEventListener("DOMContentLoaded", () => {
  const productsLinks = document.querySelectorAll(
    ".panel-b2b .before-loop-nex-to-sidebar .woocommerce-loop-product__link",
  );
  const products = document.querySelectorAll(
    ".panel-b2b .before-loop-nex-to-sidebar .woocommerce-loop-product__title",
  );

  console.log(products);

  const popup = document.querySelector(".js-product-popup");
  const popup_content = document.querySelector(".js-product-popup__content");
  const popup_close = document.querySelector(".js-product-popup__close");

  if (productsLinks.length && products.length) {
    productsLinks.forEach((productLink) => {
      productLink.removeAttribute("href");
    });

    products.forEach((product) => {
      product.addEventListener("click", (event) => {
        event.preventDefault();
        const product_id = product
          .closest(".product")
          .querySelector(".js-b2b-product-quantity").dataset.product;

        fetch(b2b_popup_vars.ajax_url, {
          method: "POST",
          headers: {
            "Content-Type": "application/x-www-form-urlencoded",
          },
          body: new URLSearchParams({
            action: "get_product_details",
            id: product_id,
            nonce: b2b_popup_vars.security, // Pobierz wartość nonce
          }),
        })
          .then((response) => response.json())
          .then((data) => {
            popup_content.innerHTML = data.data;
            popup.classList.add("product-popup--show");
          })
          .catch((error) => console.error("Error:", error));
      });

      popup_close.addEventListener("click", (event) => {
        popup.classList.remove("product-popup--show");
      });
    });
  }
});
